{
  "name": "moriarty-eutxo-public-experiment",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test tests/*.test.mjs",
    "compile": "node src/cli.mjs compile --source examples/revision-step.mori --manifest examples/revision-step.manifest.json --out artifacts",
    "validate": "node src/cli.mjs validate --designers /home/charl/moriarty-eutxo-validation-2026-10-12/designers --manifest examples/revision-step.manifest.json --out artifacts"
  }
}

const manifestPath = arg('--manifest', join(ROOT, 'examples/revision-step.manifest.json'));
const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
const out = takeOut(join(ROOT, 'artifacts'));

if (command === 'compile') {
  const source = arg('--source', join(ROOT, 'examples/revision-step.mori'));
  const result = compilePublic({ source, manifest, outDir: out });

export function admitPublicAtomic(input, manifest) {
  if (!manifest || manifest.schemaVersion !== 'moriarty-eutxo-public-manifest/1') {
    return fail('MANIFEST_SCHEMA');
  }
  if (manifest.production === true) return fail('PRODUCTION_CLAIM_FORBIDDEN');

  },
  bound,
  manifest,
  requiredActors: [...requiredActors],
  unsupportedPrivateClaims: [...m.requiredClaims],
  privateVerification: 'explicitly-not-performed',
  admittedEffects: kinds,
};

const toolchain = spawnSync(AIKEN, ['--version'], { encoding: 'utf8', env: aikenEnv() });
const hashes = {
  sourceHash: bound.manifest.sourceHash,
  programHash: bound.programHash,
  boundsHash: bound.manifest.bounds.boundsHash,
  manifestHash: sha256(JSON.stringify(man)),
  validatorHash: sha256(lowered.validator),
  toolchain: (toolchain.stdout || '').trim(),
};
writeFileSync(join(outDir, 'atomic.ak'), lowered.validator);
writeFileSync(join(outDir, 'sample-datum.json'), JSON.stringify(lowered.sampleDatum, null, 2) + '\n');
writeFileSync(join(outDir, 'sample-redeemer.json'), JSON.stringify(lowered.sampleRedeemer, null, 2) + '\n');
writeFileSync(join(outDir, 'data-schemas.json'), JSON.stringify(lowered.schemas, null, 2) + '\n');

const ok = check.status === 0 && build.status === 0 && existsSync(blueprintSrc);
if (ok) {
  cpSync(blueprintSrc, publishedBlueprint);
  const uplcDir = join(isolated, 'artifacts');
  if (existsSync(uplcDir)) {
    mkdirSync(join(outDir), { recursive: true });
    for (const name of readdirSync(uplcDir).filter(n => n.endsWith('.uplc'))) {
      cpSync(join(uplcDir, name), join(outDir, name));
    }
  }
  writeFileSync(join(PROJECT, 'validators/atomic.ak'), lowered.validator);
  cpSync(publishedBlueprint, join(PROJECT, 'plutus.json'));
}
return {
  ok,
  admission: admitted,
  metadata: { ...lowered.metadata, hashes, positiveUplcValidation: lowered.positiveUplcValidation === true },
  check: {
    status: check.status,
    stdout: check.stdout,
    stderr: check.stderr,
    tests: parsed.tests,
    summary: parsed.summary,
    parseOk: parsed.ok,
    parseErrors: parsed.errors,
    missingTests: testMatch.missing,
    unexpectedFail: testMatch.unexpectedFail,
  },
  build: { status: build.status, stdout: build.stdout, stderr: build.stderr },
  artifacts: outDir,
  validatorPath: join(outDir, 'atomic.ak'),
  blueprintPath: ok && existsSync(publishedBlueprint) ? publishedBlueprint : null,
  positiveUplcValidation: ok && lowered.positiveUplcValidation === true,

const result = compilePublic({ source, manifest, outDir: out });
process.stdout.write(JSON.stringify({
  ok: result.ok,
  programHash: result.metadata?.programHash,
  admission: result.admission?.ok === false ? result.admission : { ok: true, capability: result.admission?.capability, privateVerification: result.admission?.privateVerification },
  checkStatus: result.check?.status,
  buildStatus: result.build?.status,
  artifacts: result.artifacts,
  blueprint: result.blueprintPath,
  validator: result.validatorPath,
  checkStderr: result.ok ? undefined : result.check?.stderr,
  buildStderr: result.ok ? undefined : result.build?.stderr,
}, null, 2) + '\n');
process.exit(result.ok ? 0 : 1);

const expectedTests = [...lowered.expectedTests, ...bound.expectedTests];
if (syntheticTime) expectedTests.push({ title: 'sibling_frozen_program_hash_differs', status: 'success' });
const validatorPath = join(outDir, 'custody.ak');
writeFileSync(validatorPath, validator);
const isolated = createIsolatedCustodyProject();
const published = join(outDir, 'plutus.json');
try {

const { compileCustody } = await import('./compile-custody.mjs');
const compileRoot = evidenceRoot || REPAIR_ROOT;
const outDir = join(compileRoot, 'checks/source-compile', sha256);
const compiled = compileCustody({
  sourcePath,
  seedPath,
  casesPath: join(DESIGNER, 'cases.json'),
  expectedReleasePath: join(DESIGNER, 'E13-release-real-custody.expected.json'),
  expectedRefundPath: join(DESIGNER, 'E11-refund-real-custody.expected.json'),
  residualPath: join(DESIGNER, 'financial-residual-custody-v5.json'),
  manifest,
  outDir,
});
if (!compiled.ok || !compiled.blueprintPath || !existsSync(compiled.blueprintPath)) {
  return closed(compiled.code || 'SOURCE_COMPILE_FAILED', {
    compiled: false,
    sha256,
    admitted: true,
    path: sourcePath,
    checkStatus: compiled.check?.status ?? null,
    buildStatus: compiled.build?.status ?? null,
    missing: compiled.check?.missing || compiled.missingTests || null,
  });
}
const cacheDir = evidenceRoot ? join(evidenceRoot, 'checks/source-cache') : SOURCE_CACHE;
mkdirSync(cacheDir, { recursive: true });
const blueprintPath = join(cacheDir, `${sha256}.plutus.json`);
cpSync(compiled.blueprintPath, blueprintPath);
const blueprintSha256 = fileHash(blueprintPath);
const record = {
  sourceHash: sha256,
  seedHash,
  manifestHash,
  aikenRealpath: identity?.real || null,
  aikenVersion: identity?.version || null,
  checkStatus: compiled.check?.status ?? null,
  buildStatus: compiled.build?.status ?? null,
  blueprintPath,
  blueprintSha256,
  commands: ['check', 'build --uplc'],
};
const recordPath = join(cacheDir, `${sha256}.json`);
writeFileSync(recordPath, `${JSON.stringify(record, null, 2)}\n`);
return {
  ok: true,
  code: 'SOURCE_COMPILED',
  sha256,
  path: sourcePath,
  compiled: true,
  admitted: true,
  cacheHit: false,
  compilerInvoked: true,
  checkStatus: record.checkStatus,
  buildStatus: record.buildStatus,
  blueprintPath,
  blueprintSha256,
  aiken: record.aikenRealpath,
  aikenVersion: record.aikenVersion,
  hashes: admitted.hashes,
  instanceId: admitted.instanceId,
  commands: record.commands,

  if (persistDir) {
    writeFileSync(join(persistDir, 'plutus.applied.json'), JSON.stringify(appliedBp));
    writeFileSync(join(persistDir, 'cash.script.json'), JSON.stringify({
      type: 'PlutusScriptV3',
      description: 'fail-closed cash measurement validator',
      cborHex: cash.compiledCode,
    }));
    writeFileSync(join(persistDir, 'apply-report.json'), JSON.stringify(report, null, 2) + '\n');
  }
  return report;
}

  const scriptPath = join(workDir, 'head.applied.script.json');
  writeFileSync(scriptPath, JSON.stringify({
    type: 'PlutusScriptV3',
    description: 'financial head applied to the approved cash policy',
    cborHex: appliedMint.compiledCode,
  }));
  return {
    ok: true,
    code: 'HEAD_APPLIED_TO_CASH_POLICY',
    appliedHash: appliedMint.hash,
    unappliedHash: head.hash,
    cashPolicyId,
    unusedFailClosedCash: embedded.hash,
    instanceId: instance.instanceId,
    genesis: genesis.genesis,
    scriptPath,
    unitRoles: manifest.unitFixture === true,
    ledgerExecution: false,
    nativePins: false,
    cashCanMint: false,
  };
}

}
const head = stages.inputs.head;
const headApply = applyHeadToCashPolicy({
  blueprintPath: stages.source.blueprintPath,
  cashPolicyId: cashCompile.policyId,
  hashes,
  manifest,
  seedTxId: head.txId,
  seedIndex: head.index,
  workDir: join(workDir, 'head'),
});
if (!headApply.ok) {

let addressArgs;
if (spec.outputScriptPath) {
  if (!plutusScriptFile(spec.outputScriptPath)) return closed('OUTPUT_SCRIPT_REJECTED');
  addressArgs = ['address', 'build', '--payment-script-file', spec.outputScriptPath, '--testnet-magic', magic.text];

if (mintText) {
  const real = isRealCli(cliPath);
  let script = spec.mintScriptPath || null;
  if (!script) {
    if (real) return closed('MINT_SCRIPT_ABSENT');
    script = join(dir, 'mint.marker');
    writeFileSync(script, 'unit-marker-not-a-compiled-cash-policy\n');
  } else if (real && !plutusScriptFile(script)) {
    return closed('MINT_SCRIPT_REJECTED');
  }
  args.push('--mint', mintText, '--mint-script-file', script, '--mint-redeemer-value', '{"int":0}');

const args = [
  'conway', 'transaction', 'build-raw',
  '--tx-in', head,
  '--tx-in-script-file', spec.spendScriptPath,
  '--tx-in-redeemer-file', redeemerFile,
];
